const D = { density:.5, energy:.55, hue:28, speed:1, scale:1, x:.5, y:.5, style:'pastel', act:'sunrise', seed:0, warmth:.6, haze:.45 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const frc=v=>v-Math.floor(v);
const md=(a,n)=>((a%n)+n)%n;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const lrp=(a,b,t)=>a+(b-a)*t;

const W=width,Hh=height,u=Math.min(W,Hh);
const H=md(P.hue,360);
const style=P.style;
const dark = style==='nocturne';
const en=P.energy*(.5+.5*K.intensity);
// act: sunrise = warmth/brightness climb with section; drift = static-time, clouds only weather engine
const act=P.act;
const dayT = act==='sunrise' ? clp(K.section/7 + K.intensity*0.25, 0, 1) : 0.45;

// t0 reset guard
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat;
S.lastBeat=K.beat;

// ---- palette anchors per style (zenith -> horizon) ----
function pal(){
  if(dark) return {zen:[md(H+250,360),52,20], mid:[md(H+210,360),40,30], hor:[md(H,360),34,40], glow:[md(H+8,360),46,58]};
  if(style==='gradient_map') return {zen:[md(H+265,360),34,80], mid:[md(H+40,360),40,86], hor:[md(H,360),52,92], glow:[md(H+12,360),60,98]};
  return {zen:[md(H+258,360),24,84], mid:[md(H+34,360),30,90], hor:[md(H,360),40,91], glow:[md(H+10,360),46,98]};
}

// ---- static sky buffer, keyed size+style+seed+hue-bucket+dayBucket ----
const hb=Math.round(H/6), db=Math.round(dayT*5);
const key=W+'x'+Hh+':'+style+':'+P.seed+':'+hb+':'+db+':'+Math.round(P.warmth*4)+':'+Math.round(P.haze*4);
if(!S.sky||S.key!==key){
  S.key=key;
  const g=createGraphics(W,Hh); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const pl=pal();
  const post = style==='gradient_map';
  const bands=post?7:150;
  const horizonY=0.66; // fraction where sun sits
  for(let i=0;i<bands;i++){
    let f=i/(bands-1);
    let h,s,b;
    if(f<0.55){const tt=f/0.55; h=lrp(pl.zen[0],pl.mid[0],tt); s=lrp(pl.zen[1],pl.mid[1],tt); b=lrp(pl.zen[2],pl.mid[2],tt);}
    else{const tt=(f-0.55)/0.45; h=lrp(pl.mid[0],pl.hor[0],tt); s=lrp(pl.mid[1],pl.hor[1],tt); b=lrp(pl.mid[2],pl.hor[2],tt);}
    // brightness lift toward day
    b=clp(b+dayT*8-((1-P.warmth)*4), 6, 96);
    g.fill(md(h,360),s,b);
    const y0=i*Hh/bands;
    g.rect(0,y0-1,W,Hh/bands+2);
  }
  // horizon sun-glow bloom baked (soft)
  const gx=P.x*W, gy=horizonY*Hh;
  g.blendMode(ADD);
  for(let r=0;r<5;r++){
    const rad=u*(0.5-r*0.08)*(0.8+P.warmth*0.6);
    g.fill(pl.glow[0],pl.glow[1]*0.7,pl.glow[2],9+dayT*7);
    g.ellipse(gx,gy,rad*2,rad*1.3);
  }
  g.blendMode(BLEND);
  // texture pass
  if(style==='halftone'){
    // riso-ish halftone dots, size by local darkness (sampled from a gradient proxy)
    const step=Math.max(7,Math.round(u/56));
    g.fill(md(H,360),44,dark?70:100,dark?26:22);
    for(let yy=step/2;yy<Hh;yy+=step){
      const shade=yy/Hh; // darker toward top
      for(let xx=(Math.floor(yy/step)%2)*step/2;xx<W;xx+=step){
        const rr=step*(0.16+(1-shade)*0.42);
        g.ellipse(xx,yy,rr,rr);
      }
    }
  } else if(style==='watercolor'){
    // soft blooming blotches with paper grain
    for(let i=0;i<46;i++){
      const bx=fr(i*4+1)*W, by=fr(i*4+2)*Hh, br=u*(0.05+fr(i*4+3)*0.16);
      const c=(fr(i)<0.5)?pl.mid:pl.hor;
      g.fill(md(c[0]+ (fr(i*7)-0.5)*30,360),c[1]*0.8,c[2],5);
      g.ellipse(bx,by,br*2,br*1.6);
    }
  }
  // fine grain everywhere (chalky pastel tooth)
  const gn=Math.round(1400*(0.6+P.haze));
  for(let i=0;i<gn;i++){
    const gx2=fr(i*3+50)*W, gy2=fr(i*3+51)*Hh, a=fr(i*3+52);
    g.fill(0,0,a<0.5?100:0,3.2*P.haze+1.2);
    g.rect(gx2,gy2,1.4,1.4);
  }
  S.sky=g;
  // rebuild seed-dependent cloud + star geometry
  S.seedUsed=P.seed; S.buildClouds=true;
}

// ---- seed cloud/star geometry ----
if(S.seedUsed!==P.seed||S.buildClouds||!S.clouds){
  S.seedUsed=P.seed; S.buildClouds=false;
  S.clouds=[];
  for(let i=0;i<28;i++){
    const puffs=[];
    const np=3+Math.floor(fr(i*11+3)*4);
    for(let j=0;j<np;j++) puffs.push({dx:(fr(i*11+j*3+4)-0.5)*1.7, dy:(fr(i*11+j*3+5)-0.5)*0.5, r:0.5+fr(i*11+j*3+6)*0.9});
    S.clouds.push({base:fr(i*11+1), y:0.08+fr(i*11+2)*0.5, sc:0.5+fr(i*11+7)*1.1, sp:0.5+fr(i*11+8)*1.0, layer:fr(i*11+9), puffs});
  }
  S.stars=[];
  for(let i=0;i<40;i++) S.stars.push({x:fr(i*5+70), y:fr(i*5+71)*0.5, s:0.3+fr(i*5+72)*0.9, ph:fr(i*5+73)*6.2832});
}

// ---- draw baked sky ----
image(S.sky,0,0,W,Hh);

// ---- morning star (fades as day breaks) ----
const starFade=clp(1-dayT*1.15,0,1);
if(starFade>0.02){
  noStroke();
  for(const st of S.stars){
    const tw=0.55+0.45*Math.sin(K.t*(0.7+st.s)+st.ph);
    const a=starFade*tw*(0.35+st.s*0.5)*70;
    const sx=st.x*W, sy=st.y*Hh, ss=u*0.004*st.s*(1+P.scale*0.3);
    fill(md(H+200,360),16,100,a);
    ellipse(sx,sy,ss,ss);
  }
  // one bright venus
  const vtw=0.6+0.4*Math.sin(K.t*0.9);
  const vx=(0.2+0.6*fr(999))*W, vy=(0.12+0.14*fr(998))*Hh;
  fill(md(H+30,360),12,100,starFade*vtw*80);
  ellipse(vx,vy,u*0.012*(1+P.scale*0.3),u*0.012*(1+P.scale*0.3));
}

// ---- drifting clouds (real-time motion floor via K.t) ----
const nC=Math.max(2,Math.round(S.clouds.length*clp(P.density,0,1)));
const cloudA=dark?58:(style==='halftone'?0:42);
if(cloudA>0){
  noStroke();
  for(let i=0;i<nC;i++){
    const c=S.clouds[i];
    const drift=K.t*0.010*P.speed*(0.4+c.sp*0.9)*(0.6+en*0.9);
    const fx=md(c.base+drift, 1.24)-0.12;
    const cx=fx*W, cy=c.y*Hh;
    const cs=u*0.16*c.sc*(0.7+P.scale*0.4);
    const breathe=0.9+0.12*Math.sin(K.t*0.5+i)+K.swell*0.06;
    const near=0.5+c.layer*0.5;
    const cH = dark? md(H+220,360): md(H+ (c.layer<0.5?18:300), 360);
    const cB = dark? 34 : lrp(100,86,c.layer);
    const cS = dark? 26 : lrp(6,26,c.layer);
    for(const p of c.puffs){
      const a=cloudA*near*(0.5+p.r*0.5)*(0.6+en*0.6);
      fill(cH,cS,cB,clp(a,0,90));
      ellipse(cx+p.dx*cs, cy+p.dy*cs, p.r*cs*breathe*1.8, p.r*cs*breathe);
    }
  }
}

// ---- sun-glow breathe (additive, audio+swell on top of clk baseline) ----
const gx=P.x*W, gy=0.66*Hh;
const pump=K.swell*0.5 + K.pulse*0.15 + A.bass*0.5;
blendMode(ADD); noStroke();
const glowH=dark?md(H+6,360):md(H+10,360);
for(let r=0;r<4;r++){
  const rad=u*(0.34-r*0.06)*(0.85+P.warmth*0.5)*(1+pump*0.28);
  fill(glowH,dark?40:52,dark?60:100, (6+dayT*8)*(0.7+en*0.6));
  ellipse(gx,gy,rad*2,rad*1.25);
}
// treble sparkle high haze
const spk=A.treble*0.7;
if(spk>0.04){
  for(let i=0;i<10;i++){
    const sx=frc(fr(i*2+3)+K.t*0.02)*W, sy=fr(i*2+4)*Hh*0.4;
    fill(md(H+40,360),20,100,spk*40);
    ellipse(sx,sy,u*0.004,u*0.004);
  }
}
blendMode(BLEND);
